```rust
// src/channel.rs
use crate::pty::{Pty, ActivityState};
use std::collections::HashMap;

pub type ChannelId = usize;
pub type PtyId = usize;

pub struct Channel {
    pub id: ChannelId,
    pub name: String,
    pub ptys: HashMap<PtyId, Pty>,
    pub focused_pty: PtyId,
}

impl Channel {
    pub fn new(id: ChannelId, name: String, pty: Pty) -> Self {
        let pty_id = pty.id;
        let mut ptys = HashMap::new();
        ptys.insert(pty_id, pty);

        Self {
            id,
            name,
            ptys,
            focused_pty: pty_id,
        }
    }

    pub fn focused_pty(&self) -> &Pty {
        &self.ptys[&self.focused_pty]
    }

    pub fn focused_pty_mut(&mut self) -> &mut Pty {
        self.ptys.get_mut(&self.focused_pty).unwrap()
    }

    /// Aggregate activity across all PTYs
    pub fn activity(&self) -> ActivityState {
        let mut total_bells = 0u32;
        let mut has_activity = false;

        for pty in self.ptys.values() {
            match &pty.activity {
                ActivityState::Idle => {}
                ActivityState::Active(bells) => {
                    has_activity = true;
                    total_bells += bells;
                }
            }
        }

        if has_activity {
            ActivityState::Active(total_bells)
        } else {
            ActivityState::Idle
        }
    }

    pub fn clear_activity(&mut self) {
        for pty in self.ptys.values_mut() {
            pty.clear_activity();
        }
    }
}
