### Pattern: Key Handling

```rust
fn handle_key(app: &mut App, key: KeyEvent) -> Result<bool> {
    match app.input_mode {
        InputMode::Normal => {
            if key.code == KeyCode::Char('b') 
               && key.modifiers.contains(KeyModifiers::CONTROL) {
                // Enter leader mode
                app.input_mode = InputMode::Leader;
            } else {
                // Forward to PTY
                forward_to_pty(app, key)?;
            }
        }
        InputMode::Leader => {
            // Always return to normal after processing
            app.input_mode = InputMode::Normal;

            match key.code {
                // Navigation
                KeyCode::Char('j') | KeyCode::Down => {
                    next_channel(app);
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    prev_channel(app);
                }

                // Direct channel access (1-9)
                KeyCode::Char(c) if c.is_ascii_digit() && c != '0' => {
                    let idx = (c as usize) - ('1' as usize);
                    if idx < app.channels.len() {
                        switch_channel(app, idx);
                    }
                }

                // Quit
                KeyCode::Char('q') => {
                    return Ok(true); // Signal quit
                }

                // Send Ctrl+B to PTY (double-tap)
                KeyCode::Char('b') => {
                    let key = KeyEvent::new(KeyCode::Char('b'), KeyModifiers::CONTROL);
                    forward_to_pty(app, key)?;
                }

                // Cancel / unknown - just ignore
                KeyCode::Esc | _ => {}
            }
        }
    }
    Ok(false)
}
```

