### Pattern: Picker State

```rust
// src/picker.rs

pub struct Picker {
    pub query: String,
    pub selected: usize,
    pub filtered: Vec<usize>,  // Indices into channel list
}

impl Picker {
    pub fn new(channel_count: usize) -> Self {
        Self {
            query: String::new(),
            selected: 0,
            filtered: (0..channel_count).collect(),
        }
    }

    pub fn update_filter(&mut self, channels: &[Channel]) {
        if self.query.is_empty() {
            self.filtered = (0..channels.len()).collect();
        } else {
            let query_lower = self.query.to_lowercase();
            self.filtered = channels.iter()
                .enumerate()
                .filter(|(_, ch)| ch.name.to_lowercase().contains(&query_lower))
                .map(|(i, _)| i)
                .collect();
        }

        // Keep selection in bounds
        if self.selected >= self.filtered.len() {
            self.selected = self.filtered.len().saturating_sub(1);
        }
    }

    pub fn selected_channel(&self) -> Option<usize> {
        self.filtered.get(self.selected).copied()
    }

    pub fn move_up(&mut self) {
        if self.selected > 0 {
            self.selected -= 1;
        }
    }

    pub fn move_down(&mut self) {
        if self.selected + 1 < self.filtered.len() {
            self.selected += 1;
        }
    }

    pub fn push_char(&mut self, c: char, channels: &[Channel]) {
        self.query.push(c);
        self.update_filter(channels);
    }

    pub fn pop_char(&mut self, channels: &[Channel]) {
        self.query.pop();
        self.update_filter(channels);
    }
}
