### Pattern: Detect PTY Exit

```rust
// In Pty struct:
pub enum PtyStatus {
    Running,
    Exited(i32),  // Exit code
    Error(String),
}

pub struct Pty {
    // ... existing fields
    pub status: PtyStatus,
}

// In reader task, detect EOF:
loop {
    match reader.read(&mut buf) {
        Ok(0) => {
            // EOF - process exited
            let _ = tx.send(PtyMessage::Exited);
            break;
        }
        Ok(n) => {
            let _ = tx.send(PtyMessage::Data(buf[..n].to_vec()));
        }
        Err(e) => {
            let _ = tx.send(PtyMessage::Error(e.to_string()));
            break;
        }
    }
}
